import Link from "next/link";
import { cn } from "@/components/ui/cn";
import { Card, SectionHeading } from "@/components/ui/card";
import { ACTIVITIES, DIFFICULTIES } from "@/lib/memory/format";
import type { Activity, Difficulty, Session } from "@/lib/memory/types";
import type { AdminItem, ManageBase } from "./types";

/**
 * What members will see for each activity, generated by the same server
 * functions (nothing is recorded). Hidden answers are shown to staff here
 * in brackets so they can judge suitability.
 */
export function ActivityPreview({
  base,
  collectionId,
  items,
  item,
  activity,
  difficulty,
  segment,
  short,
  preview,
}: {
  base: ManageBase;
  collectionId: string;
  items: AdminItem[];
  item: AdminItem;
  activity: Activity;
  difficulty: Difficulty;
  segment: number;
  short: boolean;
  preview: (Session & { hidden: { blanks?: number[]; chips?: Array<{ id: string; from: number; to: number }> } }) | null;
}) {
  const href = (p: Partial<{ item: string; activity: string; difficulty: string; segment: number; short: boolean }>) => {
    const q = new URLSearchParams({ item: p.item ?? item.id, activity: p.activity ?? activity, difficulty: p.difficulty ?? difficulty, segment: String(p.segment ?? segment), short: (p.short ?? short) ? "1" : "0" });
    return `${base}/collections/${collectionId}/preview?${q}`;
  };
  const chip = (active: boolean) =>
    cn("inline-flex min-h-11 items-center rounded-full border px-4 text-meta font-semibold", active ? "border-primary bg-primary-soft" : "border-border bg-surface hover:bg-surface-muted");
  const parts = short ? item.passage.short_segments : item.passage.segments;
  return (
    <div className="space-y-6">
      <nav aria-label="Verse" className="flex flex-wrap gap-2">
        {items.map((i) => (
          <Link key={i.id} href={href({ item: i.id, segment: 0 })} className={chip(i.id === item.id)} aria-current={i.id === item.id ? "true" : undefined}>
            {i.passage.label}
          </Link>
        ))}
      </nav>
      <nav aria-label="Activity" className="flex flex-wrap gap-2">
        {ACTIVITIES.map((a) => (
          <Link key={a.key} href={href({ activity: a.key })} className={chip(a.key === activity)} aria-current={a.key === activity ? "true" : undefined}>
            {a.label}
          </Link>
        ))}
      </nav>
      <nav aria-label="Difficulty and part" className="flex flex-wrap gap-2">
        {DIFFICULTIES.map((d) => (
          <Link key={d.key} href={href({ difficulty: d.key })} className={chip(d.key === difficulty)} aria-current={d.key === difficulty ? "true" : undefined}>
            {d.label}
          </Link>
        ))}
        <Link href={href({ short: !short, segment: 0 })} className={chip(short)} aria-current={short ? "true" : undefined}>
          Kids parts
        </Link>
        <Link href={href({ segment: 0 })} className={chip(segment === 0)}>
          Whole passage
        </Link>
        {parts.length > 1
          ? parts.map((p) => (
              <Link key={p.n} href={href({ segment: p.n })} className={chip(segment === p.n)}>
                Part {p.n}
              </Link>
            ))
          : null}
      </nav>
      <Card>
        <SectionHeading id="what">What a member sees</SectionHeading>
        {!preview ? (
          <p className="text-text-secondary">This combination isn&apos;t available for this passage (for example, the whole of a long passage for typing or word order). Choose a part.</p>
        ) : (
          <div className="space-y-4">
            <p className="text-meta text-text-secondary">
              {preview.label} · {preview.translation.code} · {preview.segment_count} parts
            </p>
            <PreviewBody p={preview} />
            <details>
              <summary className="min-h-11 cursor-pointer py-2 font-semibold text-primary">Answer text</summary>
              <p className="memory-text">{preview.answer_text}</p>
            </details>
          </div>
        )}
      </Card>
    </div>
  );
}

function PreviewBody({ p }: { p: Session & { hidden: { blanks?: number[] } } }) {
  const s = p.setup;
  switch (p.activity) {
    case "read_repeat":
      return <p className="memory-text">{(s.tokens ?? []).map((t) => t.t + (t.g ? "" : t.b ? "\n" : " ")).join("")}</p>;
    case "flashcards":
      return (
        <p>
          <span className="font-semibold">Front:</span> {s.front}
        </p>
      );
    case "self_check":
      return <p>The member sees only the reference ({p.label}), recites, then reveals the verse and records how it went.</p>;
    case "type_verse":
      return (
        <p>
          The member types {s.words} words from memory. Capital letters {s.ignore_case ? "ignored" : "count"}, punctuation {s.ignore_punctuation ? "ignored" : "counts"} (the member&apos;s own settings).
        </p>
      );
    case "missing_words":
      return (
        <>
          <p className="memory-text">
            {(s.tokens ?? []).map((t) => (t.blank ? `${t.pre}[____ ${t.blank}]${t.post}` : t.t) + (t.g ? "" : t.b ? "\n" : " ")).join("")}
          </p>
          <p className="text-meta">
            {s.typed ? "Typed answers (Challenge)." : `Choices: ${(s.bank ?? []).map((b) => b.text + ((b.count ?? 1) > 1 ? ` ×${b.count}` : "")).join(", ")}`} · {s.blank_count} blanks
          </p>
        </>
      );
    case "word_order":
      return (
        <ul className="flex flex-wrap gap-2">
          {(s.chips ?? []).map((c) => (
            <li key={c.id} className="rounded-full border border-border bg-surface-muted px-3 py-1 font-serif">
              {c.text}
            </li>
          ))}
        </ul>
      );
  }
}
